import 'package:flutter/material.dart';

/// Material 3 (vibrant scheme) tonal palette used across the app.
///
/// The values mirror the dark `ColorScheme` generated by
/// `ColorScheme.fromSeed(seedColor: seed, dynamicSchemeVariant:
/// DynamicSchemeVariant.vibrant)`, so every hard-coded surface/accent keeps
/// the same tonal relationships as the global [AppTheme] color scheme.
class AppColors {
  /// Brand seed. Everything else is derived from this orange.
  static const Color seed = Color(0xFFFF6B00);

  // Surfaces (Material 3 dark tonal surface roles)
  static const Color background = Color(0xFF1D100A); // surface
  static const Color surface = Color(0xFF1D100A); // surface
  static const Color cardSurface = Color(0xFF2B1C15); // surfaceContainer
  static const Color surfaceLow = Color(0xFF241710); // surfaceContainerLow
  static const Color surfaceHigh = Color(0xFF413128); // surfaceContainerHighest
  static const Color border = Color(0xFF53433B); // outlineVariant

  // Primary (orange) roles
  static const Color primaryOrange = Color(0xFFFFB693); // primary
  static const Color orangeDark = Color(0xFF7A3000); // primaryContainer
  static const Color orangeSoft = Color(0x33FFB693); // primary @ 20%
  static const Color orangeBorder = Color(0x66FFB693); // primary @ 40%
  static const Color onPrimary = Color(0xFF561F00);

  // Text (on-surface roles)
  static const Color textWhite = Color(0xFFFFFFFF);
  static const Color textLight = Color(0xFFF8DDD2); // onSurface
  static const Color textSlate = Color(0xFFC9B0A4); // onSurfaceVariant
  static const Color textMuted = Color(0xFF9C8379);

  // Status / chart accents (Material 3-ish tones that read well in dark)
  static const Color emerald = Color(0xFF7DDC9A);
  static const Color amber = Color(0xFFFFD887);
  static const Color rose = Color(0xFFFFB4AB); // error
}
